{
  "headline": "Focus on clean indoor air and fitted N95 masks at {{level.name}} air quality",
  "summary": "Today's air sits at {{level.name}} with current US AQI {{aqi.now}}. Running filtration indoors delivers {{impact.diy_box_fan_filter.pct}} lower exposure, while your cleanest outdoor window is {{best.start}} to {{best.end}}.",
  "cards": [
    {
      "actionId": "diy_box_fan_filter",
      "title": "Build a DIY box fan air filter",
      "why": "A simple, low-cost filter can significantly reduce indoor PM2.5, by up to {{impact.diy_box_fan_filter.pct}}.",
      "when": "Run it continuously, especially when air quality is {{level.name}}.",
      "steps": [
        "Use a standard box fan and a MERV-13 filter.",
        "Seal the filter to the fan using tape or bungee cords.",
        "Place in the room where you spend the most time."
      ]
    },
    {
      "actionId": "air_house_in_best_window",
      "title": "Ventilate your home during cleaner air windows",
      "why": "Opening windows during the best air quality periods can help reduce indoor pollutant buildup, offering up to {{impact.air_house_in_best_window.pct}} improvement.",
      "when": "Ventilate between {{best.start}} and {{best.end}}.",
      "steps": [
        "Open windows on multiple sides of the house for cross-ventilation.",
        "Close windows before pollution levels rise again."
      ]
    },
    {
      "actionId": "n95_for_open_transport",
      "title": "Wear an N95 mask during open transport",
      "why": "An N95 mask can reduce your exposure by {{impact.n95_for_open_transport.pct}} during commutes on public transport or in shared vehicles.",
      "when": "Wear during all commutes on public transport.",
      "steps": [
        "Ensure the mask has a snug fit, covering your nose and mouth.",
        "Avoid touching the mask while wearing it."
      ]
    },
    {
      "actionId": "errands_in_best_window",
      "title": "Schedule errands for cleaner air windows",
      "why": "Conducting outdoor errands during {{best.start}} to {{best.end}} minimizes your exposure to high pollution levels.",
      "when": "Plan outdoor activities and errands during the best air quality hours.",
      "steps": [
        "Group errands together to reduce travel time.",
        "Check the air quality forecast before leaving."
      ]
    },
    {
      "actionId": "community_no_burning",
      "title": "Advocate for a community 'no burning' policy",
      "why": "Reducing local burning activities can lead to a {{impact.community_no_burning.pct}} decrease in ambient pollution.",
      "when": "Discuss with neighbors and community leaders.",
      "steps": [
        "Share information about the health impacts of burning.",
        "Encourage alternative waste disposal methods."
      ]
    },
    {
      "actionId": "share_community_brief",
      "title": "Share the Community Brief with your RWA",
      "why": "A collective effort can improve air quality for everyone, potentially reducing exposure by {{impact.share_community_brief.pct}}.",
      "when": "Share before the next society meeting.",
      "steps": [
        "Print the single-page brief.",
        "Post in society and school parent groups."
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "child",
      "note": "Keep children's outdoor play indoors while level remains {{level.name}}."
    },
    {
      "group": "adult",
      "note": "Consider reducing strenuous outdoor activities when air quality is {{level.name}}."
    }
  ],
  "tradeoffs": [
    "Building a DIY filter is low cost but requires some assembly effort.",
    "Wearing an N95 mask on public transport adds a layer of protection but can be uncomfortable for some."
  ]
}
